<?php
namespace App\Http\Controllers\Procurement;use App\Http\Controllers\Controller;use App\Models\{InventoryItem,StockTransfer,Store};use App\Services\Procurement\ProcurementService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class TransferController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('procurement.transfers.index',['rows'=>StockTransfer::with(['fromStore','toStore','items.inventoryItem'])->where('property_id',$p)->latest()->paginate(30),'stores'=>Store::where('property_id',$p)->where('is_active',1)->get(),'items'=>InventoryItem::where('property_id',$p)->where('is_active',1)->orderBy('name')->get()]);}public function store(Request $r){$d=$r->validate(['from_store_id'=>'required|different:to_store_id','to_store_id'=>'required','inventory_item_id'=>'required|array|min:1','quantity'=>'required|array','quantity.*'=>'required|numeric|min:.0001','notes'=>'nullable']);DB::transaction(function()use($d){$t=StockTransfer::create(['property_id'=>auth()->user()->property_id,'from_store_id'=>$d['from_store_id'],'to_store_id'=>$d['to_store_id'],'number'=>'TRF-'.now()->format('Ymd-His').'-'.random_int(10,99),'status'=>'submitted','notes'=>$d['notes']??null,'requested_by'=>auth()->id()]);foreach($d['inventory_item_id'] as $i=>$id)$t->items()->create(['inventory_item_id'=>$id,'quantity_requested'=>$d['quantity'][$i]]);});return back()->with('success','Stock transfer submitted.');}public function post(StockTransfer $transfer,ProcurementService $svc){abort_unless($transfer->property_id===auth()->user()->property_id,403);$svc->dispatchTransfer($transfer,auth()->id());return back()->with('success','Stock transfer completed.');}}